// === Preparar Janela ===
// Calcula a janela de tempo da execução e monta a URL do delta do Outlook.
const cfg = $('Config').first().json;
const state = $input.first()?.json ?? {};

const now = new Date();
const DAY = 86400000;
const overlapMs = Number(cfg.overlapMinutes) * 60000;

// Janela de eventos considerada (passado curto + futuro).
const timeMin = new Date(now.getTime() - Number(cfg.windowPastDays) * DAY).toISOString();
const timeMax = new Date(now.getTime() + Number(cfg.windowFutureDays) * DAY).toISOString();

// Google: filtro incremental por data de modificação.
// Na 1a execução volta initialLookbackDays; depois usa o último run
// menos uma sobreposição de segurança (evita perder eventos na borda).
const lastGoogleSync = state.last_google_sync ? new Date(state.last_google_sync) : null;
const updatedMinBase = lastGoogleSync
  ? lastGoogleSync.getTime()
  : now.getTime() - Number(cfg.initialLookbackDays) * DAY;
const updatedMin = new Date(updatedMinBase - overlapMs).toISOString();

// Outlook: usa o deltaLink guardado; se não existir, abre um novo delta.
const outlookUrl = state.outlook_delta_link
  ? state.outlook_delta_link
  : `${cfg.outlookCalendarBase}/calendarView/delta`
    + `?startDateTime=${encodeURIComponent(timeMin)}`
    + `&endDateTime=${encodeURIComponent(timeMax)}`;

return [{
  json: {
    runAt: now.toISOString(),
    updatedMin,
    timeMin,
    timeMax,
    outlookUrl,
    outlookDeltaReused: Boolean(state.outlook_delta_link),
    firstRun: !lastGoogleSync && !state.outlook_delta_link,
  },
}];

// === Coletar Google ===
// A paginação do nó HTTP devolve um item por página. Aqui achatamos
// tudo em UM item, para que o nó do Outlook execute apenas uma vez.
const events = [];
let pages = 0;

for (const item of $input.all()) {
  const body = item.json ?? {};
  pages += 1;
  if (Array.isArray(body.items)) events.push(...body.items);
}

return [{ json: { source: 'google', pages, count: events.length, events } }];

// === Coletar Outlook ===
// Achata as páginas do delta e captura o @odata.deltaLink da última
// página — é o token que será guardado para a próxima execução.
const events = [];
let deltaLink = null;
let pages = 0;

for (const item of $input.all()) {
  const body = item.json ?? {};
  pages += 1;
  if (Array.isArray(body.value)) events.push(...body.value);
  if (body['@odata.deltaLink']) deltaLink = body['@odata.deltaLink'];
}

return [{ json: { source: 'outlook', pages, count: events.length, deltaLink, events } }];

// =====================================================================
// === Reconciliar ===
// Cérebro do fluxo. Compara o que mudou em cada lado com a tabela de
// mapeamento e decide o que criar / atualizar / apagar no outro lado.
//
// Garantias:
//  - ANTI-LOOP: alteração cujo hash de conteúdo é igual ao já registrado
//    é um eco da nossa própria escrita e é descartada.
//  - ANTI-DUPLICATA: eventos marcados como espelho (extendedProperties no
//    Google, categoria no Outlook) nunca geram um novo espelho.
//  - CONFLITO: last-write-wins por lastModifiedDateTime / updated.
//    Exclusão sempre vence uma edição concorrente.
// =====================================================================

const cfg = $('Config').first().json;
const gData = $('Coletar Google').first().json;
const oData = $('Coletar Outlook').first().json;

// O nó de mapeamento tem alwaysOutputData=true, então na primeira
// execução chega um item vazio — filtramos pelo id.
const mappings = $input.all().map((i) => i.json).filter((r) => r && r.id != null);

