const MARKER = 'n8n-cal-sync';

// ---------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

function contentHash(n) {
  const key = [n.subject, n.location, n.allDay ? 'AD' : 'TS', n.start, n.end].join('');
  return `${fnv1a(key)}${fnv1a(key.split('').reverse().join(''))}`;
}

function isoUtc(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

// Graph devolve "2026-09-10T14:00:00.0000000" + timeZone (UTC via header Prefer)
function graphToIso(slot) {
  if (!slot || !slot.dateTime) return null;
  const raw = String(slot.dateTime);
  const hasZone = /(Z|[+-]\d{2}:?\d{2})$/.test(raw);
  return isoUtc(hasZone ? raw : `${raw}Z`);
}

function truncate(text, max) {
  const s = String(text ?? '').trim();
  return s.length > max ? `${s.slice(0, max - 1)}…` : s;
}

// ---------------------------------------------------------------------
// Normalização: reduz os dois formatos ao mesmo objeto canônico
// (apenas assunto + horário + local — sem participantes, sem descrição)
// ---------------------------------------------------------------------
function normalizeGoogle(ev) {
  const allDay = Boolean(ev.start && ev.start.date);
  const n = {
    subject: truncate(ev.summary || '(sem título)', 250),
    location: truncate(ev.location || '', 250),
    allDay,
    start: allDay ? ev.start.date : isoUtc(ev.start && ev.start.dateTime),
    end: allDay ? ev.end.date : isoUtc(ev.end && ev.end.dateTime),
  };
  n.hash = contentHash(n);
  return n;
}

function normalizeOutlook(ev) {
  const allDay = Boolean(ev.isAllDay);
  const startIso = graphToIso(ev.start);
  const endIso = graphToIso(ev.end);
  const n = {
    subject: truncate(ev.subject || '(sem título)', 250),
    location: truncate((ev.location && ev.location.displayName) || '', 250),
    allDay,
    start: allDay && startIso ? startIso.slice(0, 10) : startIso,
    end: allDay && endIso ? endIso.slice(0, 10) : endIso,
  };
  n.hash = contentHash(n);
  return n;
}

// ---------------------------------------------------------------------
// Payloads de escrita
// ---------------------------------------------------------------------
function googleBody(n, opts) {
  const body = {
    summary: n.subject,
    location: n.location || undefined,
    start: n.allDay ? { date: n.start } : { dateTime: n.start, timeZone: 'UTC' },
    end: n.allDay ? { date: n.end } : { dateTime: n.end, timeZone: 'UTC' },
    reminders: { useDefault: false, overrides: [] },
  };
  if (opts && opts.sourceId) {
    body.extendedProperties = {
      private: { syncApp: MARKER, syncSource: 'outlook', syncSourceId: opts.sourceId },
    };
  }
  return body;
}

function outlookBody(n, opts, conf) {
  const toGraph = (value, isEnd) => (n.allDay
    ? { dateTime: `${value}T00:00:00`, timeZone: 'UTC' }
    : { dateTime: String(value).replace(/\.\d+Z$|Z$/, ''), timeZone: 'UTC' });
  const body = {
    subject: n.subject,
    isAllDay: n.allDay,
    isReminderOn: false,
    start: toGraph(n.start, false),
    end: toGraph(n.end, true),
    location: { displayName: n.location || '' },
  };
  if (opts && opts.sourceId) {
    body.categories = [conf.mirrorCategory];
    body.singleValueExtendedProperties = [
      { id: `String {${conf.graphPropGuid}} Name SyncApp`, value: MARKER },
      { id: `String {${conf.graphPropGuid}} Name SyncSourceId`, value: opts.sourceId },
    ];
  }
  return body;
}

// ---------------------------------------------------------------------
// Reconciliação
// ---------------------------------------------------------------------
function reconcile(conf, googleEvents, outlookEvents, mapRows) {
  const stats = {
    googleRecebidos: googleEvents.length,
    outlookRecebidos: outlookEvents.length,
    mapeamentos: mapRows.length,
    ecos: 0,
    espelhosIgnorados: 0,
    fora_da_janela: 0,
    conflitos: 0,
    ignorados_por_filtro: 0,
  };

  const byGoogle = new Map();
  const byOutlook = new Map();
  for (const m of mapRows) {
    if (m.google_event_id) byGoogle.set(String(m.google_event_id), m);
    if (m.outlook_event_id) byOutlook.set(String(m.outlook_event_id), m);
  }

  const skipRe = conf.skipRegex ? new RegExp(conf.skipRegex, 'i') : null;
  const pending = [];
  const seen = new Set();

  const windowStart = conf.timeMin ? new Date(conf.timeMin).getTime() : null;
  const windowEnd = conf.timeMax ? new Date(conf.timeMax).getTime() : null;
  const inWindow = (n) => {
    if (!windowStart || !windowEnd || !n.start) return true;
    const t = new Date(n.allDay ? `${n.start}T12:00:00Z` : n.start).getTime();
    return t >= windowStart && t <= windowEnd;
  };

  // ---------- lado Google ----------
  for (const ev of googleEvents) {
    if (!ev || !ev.id) continue;
    const key = `g:${ev.id}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const mapping = byGoogle.get(String(ev.id)) || null;
    const isMirror = ev.extendedProperties
      && ev.extendedProperties.private
      && ev.extendedProperties.private.syncApp === MARKER;

    // Cancelado / apagado
    if (ev.status === 'cancelled') {
      if (mapping) {
        pending.push({
          side: 'google', type: 'delete', mapping,
          srcUpdated: isoUtc(ev.updated) || new Date().toISOString(),
        });
      }
      continue;
    }

    const n = normalizeGoogle(ev);
    if (!n.start || !n.end) continue;

    if (skipRe && skipRe.test(n.subject)) { stats.ignorados_por_filtro++; continue; }

    if (!mapping) {
      if (isMirror) { stats.espelhosIgnorados++; continue; } // espelho órfão: nunca duplicar
      if (!inWindow(n)) { stats.fora_da_janela++; continue; }
      pending.push({
        side: 'google', type: 'create', n,
        sourceId: String(ev.id), srcUpdated: isoUtc(ev.updated),
      });
      continue;
    }

    if (n.hash === mapping.last_hash) { stats.ecos++; continue; } // ANTI-LOOP

    pending.push({
      side: 'google', type: 'update', mapping, n, srcUpdated: isoUtc(ev.updated),
    });
  }

  // ---------- lado Outlook ----------
  for (const ev of outlookEvents) {
    if (!ev || !ev.id) continue;
    const key = `o:${ev.id}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const mapping = byOutlook.get(String(ev.id)) || null;

    if (ev['@removed']) {
      if (mapping) {
        pending.push({
          side: 'outlook', type: 'delete', mapping, srcUpdated: new Date().toISOString(),
        });
      }
      continue;
    }

    if (ev.isCancelled === true) {
      if (mapping) {
        pending.push({
          side: 'outlook', type: 'delete', mapping,
          srcUpdated: isoUtc(ev.lastModifiedDateTime) || new Date().toISOString(),
        });
      }
      continue;
    }

    const n = normalizeOutlook(ev);
    if (!n.start || !n.end) continue;

    if (skipRe && skipRe.test(n.subject)) { stats.ignorados_por_filtro++; continue; }

    const isMirror = Array.isArray(ev.categories) && ev.categories.includes(conf.mirrorCategory);

    if (!mapping) {
      if (isMirror) { stats.espelhosIgnorados++; continue; }
      if (!inWindow(n)) { stats.fora_da_janela++; continue; }
      pending.push({
        side: 'outlook', type: 'create', n,
        sourceId: String(ev.id), srcUpdated: isoUtc(ev.lastModifiedDateTime),
      });
      continue;
    }

    if (n.hash === mapping.last_hash) { stats.ecos++; continue; } // ANTI-LOOP

    pending.push({
      side: 'outlook', type: 'update', mapping, n, srcUpdated: isoUtc(ev.lastModifiedDateTime),
    });
  }

  // ---------- resolução de conflitos (mesmo par alterado nos 2 lados) ----------
  const byPair = new Map();
  const resolved = [];
  for (const p of pending) {
    if (!p.mapping) { resolved.push(p); continue; }
    const id = String(p.mapping.id);
    if (!byPair.has(id)) { byPair.set(id, p); continue; }

    stats.conflitos++;
    const other = byPair.get(id);

    // Exclusão sempre vence uma edição concorrente.
    if (p.type === 'delete' && other.type !== 'delete') { byPair.set(id, p); continue; }
    if (other.type === 'delete' && p.type !== 'delete') { continue; }
    if (p.type === 'delete' && other.type === 'delete') { continue; } // já apagado nos dois lados

    // last-write-wins
    const tP = p.srcUpdated ? new Date(p.srcUpdated).getTime() : 0;
    const tO = other.srcUpdated ? new Date(other.srcUpdated).getTime() : 0;
    if (tP > tO) byPair.set(id, p);
  }
  resolved.push(...byPair.values());

  // ---------- geração das ações ----------
  const actions = [];
  for (const p of resolved) {
    const m = p.mapping;

    if (p.type === 'delete') {
      if (p.side === 'google') {
        // apagado no Google -> apagar no Outlook
        actions.push({
          action: 'o_delete',
          targetEventId: m.outlook_event_id,
          ctx: { mappingId: m.id, reason: 'deleted-on-google' },
        });
      } else {
        actions.push({
          action: 'g_delete',
          targetEventId: m.google_event_id,
          ctx: { mappingId: m.id, reason: 'deleted-on-outlook' },
        });
      }
      continue;
    }

    if (p.type === 'create') {
      if (p.side === 'google') {
        actions.push({
          action: 'o_create',
          payload: outlookBody(p.n, { sourceId: p.sourceId }, conf),
          ctx: {
            origin: 'google',
            googleEventId: p.sourceId,
            googleUpdated: p.srcUpdated,
            hash: p.n.hash,
            subject: p.n.subject,
          },
        });
      } else {
        actions.push({
          action: 'g_create',
          payload: googleBody(p.n, { sourceId: p.sourceId }),
          ctx: {
            origin: 'outlook',
            outlookEventId: p.sourceId,
            outlookUpdated: p.srcUpdated,
            hash: p.n.hash,
            subject: p.n.subject,
          },
        });
      }
      continue;
    }

    // update
    if (p.side === 'google') {
      actions.push({
        action: 'o_update',
        targetEventId: m.outlook_event_id,
        payload: outlookBody(p.n, null, conf),
        ctx: {
          mappingId: m.id,
          hash: p.n.hash,
          googleUpdated: p.srcUpdated,
          subject: p.n.subject,
        },
      });
    } else {
      actions.push({
        action: 'g_update',
        targetEventId: m.google_event_id,
        payload: googleBody(p.n, null),
        ctx: {
          mappingId: m.id,
          hash: p.n.hash,
          outlookUpdated: p.srcUpdated,
          subject: p.n.subject,
        },
      });
    }
  }

  stats.acoes = actions.length;
  return { actions, stats };
}
// PURE>>>

const conf = {
  mirrorCategory: cfg.mirrorCategory,
  graphPropGuid: cfg.graphPropGuid,
  skipRegex: cfg.skipRegex || '',
  timeMin: $('Preparar Janela').first().json.timeMin,
  timeMax: $('Preparar Janela').first().json.timeMax,
};

const { actions, stats } = reconcile(
  conf,
  gData.events || [],
  oData.events || [],
  mappings,
);

// O item sentinela garante que o ramo "Nada a Fazer" -> "Salvar Estado"
// execute mesmo quando não há nenhuma alteração a propagar.
const out = actions.map((a) => ({ json: a }));
out.push({ json: { action: 'noop', stats } });
return out;

// === Consolidar Escritas ===
// Roda uma vez por item (Run Once for Each Item) para poder usar
// $('Reconciliar').item, que resolve o item de origem pareado.
// Junta a resposta da API com o contexto da ação e decide a operação
// que será feita na tabela de mapeamento.

const src = $('Reconciliar').item.json;
const res = $json ?? {};
const ctx = src.ctx ?? {};

// Se a chamada HTTP falhou (onError = continue), não mexemos no mapeamento:
// o evento continua "pendente" e será reprocessado na próxima execução.
if (res.error || res.__ok === false) {
  return {
    json: {
      op: 'skip',
      action: src.action,
      subject: ctx.subject ?? null,
      erro: typeof res.error === 'object' ? JSON.stringify(res.error).slice(0, 500) : String(res.error ?? 'desconhecido'),
    },
  };
}

switch (src.action) {
  case 'o_create':
    return {
      json: {
        op: 'insert',
        action: src.action,
        subject: ctx.subject ?? null,
        googleEventId: ctx.googleEventId,
        outlookEventId: res.id,
        origin: 'google',
        hash: ctx.hash,
        googleUpdated: ctx.googleUpdated ?? null,
        outlookUpdated: res.lastModifiedDateTime ?? null,
      },
    };

  case 'g_create':
    return {
      json: {
        op: 'insert',
        action: src.action,
        subject: ctx.subject ?? null,
        googleEventId: res.id,
        outlookEventId: ctx.outlookEventId,
        origin: 'outlook',
        hash: ctx.hash,
        googleUpdated: res.updated ?? null,
        outlookUpdated: ctx.outlookUpdated ?? null,
      },
    };

  case 'o_update':
    return {
      json: {
        op: 'update',
        action: src.action,
        subject: ctx.subject ?? null,
        mappingId: ctx.mappingId,
        hash: ctx.hash,
        googleUpdated: ctx.googleUpdated ?? null,
        outlookUpdated: res.lastModifiedDateTime ?? null,
      },
    };

  case 'g_update':
    return {
      json: {
        op: 'update',
        action: src.action,
        subject: ctx.subject ?? null,
        mappingId: ctx.mappingId,
        hash: ctx.hash,
        googleUpdated: res.updated ?? null,
        outlookUpdated: ctx.outlookUpdated ?? null,
      },
    };

  case 'g_delete':
  case 'o_delete':
    return {
      json: {
        op: 'delete',
        action: src.action,
        mappingId: ctx.mappingId,
        reason: ctx.reason ?? null,
      },
    };

  default:
    return { json: { op: 'skip', action: src.action ?? 'desconhecida' } };
}
